from auto_config.generator.gnb.managed_objects.managed_object import ManagedObject


class ApeqmParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        if self.enb_ent_config['is_ecpri']:
            self.set_parameter('eCpriOutOfTimingWindowMinorThreshold', '-3')
            self.set_parameter('sfpOperatorMode', 'false')
            self.set_parameter('aldScanningInterval', 'disabled')
